public static int calculateTimeNeeded(int N) {
    try {
        // For 3 or fewer people, no time is needed to reverse the seating order
        if (N <= 3) {
            return 0;
        }
        // The required time grows by 2 minutes for each additional person beyond the 3rd.
        // Using long to avoid overflow for very large inputs.
        long time = 2L * (N - 3);
        // Clamp the result to the maximum value representable by int
        if (time > Integer.MAX_VALUE) {
            return Integer.MAX_VALUE;
        }
        return (int) time;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return 0
        return 0;
    }
}

