        }

        int rows = grid.length;
        // Determine maximum columns to size stacks appropriately
        int maxCols = 0;
        for (int i = 0; i < rows; i++) {
            if (grid[i] != null && grid[i].length > maxCols) {
                maxCols = grid[i].length;
            }
        }
        if (maxCols == 0) {
            return 0;
        }

        boolean[][] visited = new boolean[rows][];
        for (int i = 0; i < rows; i++) {
            int len = (grid[i] != null) ? grid[i].length : 0;
            visited[i] = new boolean[len];
        }

        // Offsets for 8 directions
        int[] dR = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dC = {-1, 0, 1, -1, 1, -1, 0, 1};

        int deposits = 0;
        // Simple array-based stack
        int stackSize = rows * maxCols;
        int[] stackI = new int[stackSize];
        int[] stackJ = new int[stackSize];
        int top;

        for (int i = 0; i < rows; i++) {
            if (grid[i] == null) continue;
            int cols = grid[i].length;
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != '@' || visited[i][j]) {
                    continue;
                }
                // New component found
                deposits++;
                // DFS
                top = -1;
                stackI[++top] = i;
                stackJ[top] = j;
                visited[i][j] = true;

                while (top >= 0) {
                    int r = stackI[top];
                    int c = stackJ[top];
                    top--;

                    for (int dir = 0; dir < 8; dir++) {
                        int nr = r + dR[dir];
                        int nc = c + dC[dir];
                        if (nr < 0 || nr >= rows || grid[nr] == null) continue;
                        if (nc < 0 || nc >= grid[nr].length) continue;
                        if (!visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stackI[++top] = nr;
                            stackJ[top] = nc;
                        }
                    }
                }
            }
        }
        return deposits;
    } catch (Exception e) {
