        if (n <= 0) return "cannot be travelled";
        if (start == null || end == null || start.length != 1 || end.length != 1) return "cannot be travelled";
        int startNode = start[0];
        int endNode = end[0];
        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) return "cannot be travelled";
        // Build adjacency list
        java.util.List<Integer>[] graph = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
        if (paths != null) {
            for (int[] p : paths) {
                if (p == null || p.length != 2) return "cannot be travelled";
                int u = p[0], v = p[1];
                if (u < 0 || u >= n || v < 0 || v >= n) return "cannot be travelled";
                graph[u].add(v);
                graph[v].add(u);
            }
        }
        // BFS
        boolean[] visited = new boolean[n];
        java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
        queue.add(startNode);
