        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endNode) return "can be travelled";
            for (int nb : graph[cur]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
