public static String convertDatesToWeekdays(String date) {
    try {
        if (date == null) {
            return "Invalid input";
        }
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            return "Invalid input";
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        java.time.format.DateTimeFormatter monthFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM", java.util.Locale.ENGLISH);
        java.time.format.DateTimeFormatter weekdayFormatter =
                java.time.format.DateTimeFormatter.ofPattern("EEEE", java.util.Locale.ENGLISH);

        String monthName = localDate.format(monthFormatter);
        String weekday = localDate.format(weekdayFormatter);

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (NumberFormatException | java.time.DateTimeException e) {
        return "Invalid input";
    }
}

