public double trimMean(int[] arr) {
    try {
        if (arr == null || arr.length == 0) {
            return 0.0;
        }
        int n = arr.length;
        int removeCount = (int) Math.floor(n * 0.05);
        // Fast partial sort: sort entire array for simplicity
        java.util.Arrays.sort(arr);
        long sum = 0;
        for (int i = removeCount; i < n - removeCount; i++) {
            sum += arr[i];
        }
        int remaining = n - 2 * removeCount;
        if (remaining <= 0) {
            return 0.0;
        }
        return sum / (double) remaining;
    } catch (Exception e) {
        // In case of any unexpected error, return 0.0
        return 0.0;
    }
}

