    // Check remainder 0 pairs
    if (count[0] % 2 != 0) {
        return false;
    }
    // Check pairs of remainders that sum to k
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // when k is even and remainder is k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[complement]) {
                return false;
            }
        }
    }
