    }

    // Invalid divisor
    if (k <= 0) {
        return false;
    }

    // Count remainders modulo k
    int[] count = new int[k];
    for (int num : arr) {
        int rem = Math.floorMod(num, k); // ensures non-negative remainder
        count[rem]++;
    }

    // Remainder 0 elements must pair among themselves
    if (count[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 elements also must pair among themselves
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }

    // For other remainders, counts must be equal to complementary remainder counts
    int limit = k / 2;
    // For odd k, floor division is fine; for even k, exclude k/2 where handled above
    for (int r = 1; r < limit; r++) {
        if (count[r] != count[k - r]) {
            return false;
        }
    }

    return true;
}

