    int n = nums.length;
    int total = 0;
    for (int v : nums) {
        total += v;
    }
    // Only need to check subset sizes up to n/2 (symmetry)
    int mid = n / 2;
    int leftSize = mid;
    int rightSize = n - mid;

    // Generate all subset sums for left half
    java.util.Map<Integer, java.util.List<Integer>> leftSums = new java.util.HashMap<>();
    for (int mask = 0; mask < (1 << leftSize); mask++) {
        int cnt = 0;
        int sum = 0;
        for (int i = 0; i < leftSize; i++) {
            if ((mask & (1 << i)) != 0) {
                cnt++;
                sum += nums[i];
            }
        }
        leftSums.computeIfAbsent(cnt, k -> new java.util.ArrayList<>()).add(sum);
    }

    // Generate all subset sums for right half into sets for quick lookup
    java.util.Map<Integer, java.util.Set<Integer>> rightSets = new java.util.HashMap<>();
    for (int mask = 0; mask < (1 << rightSize); mask++) {
        int cnt = 0;
        int sum = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                cnt++;
                sum += nums[leftSize + i];
            }
        }
        rightSets.computeIfAbsent(cnt, k -> new java.util.HashSet<>()).add(sum);
    }

    // Try each possible subset size
    for (int k = 1; k <= n - 1; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        // k1: size chosen from left half
        for (int k1 = Math.max(0, k - rightSize); k1 <= Math.min(k, leftSize); k1++) {
            int k2 = k - k1;
            java.util.List<Integer> sumsLeft = leftSums.get(k1);
            java.util.Set<Integer> sumsRight = rightSets.get(k2);
            if (sumsLeft == null || sumsRight == null) {
                continue;
            }
            for (int sLeft : sumsLeft) {
                int needed = target - sLeft;
                if (sumsRight.contains(needed)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }

    // dp[0] and dp[1] are the minimal costs to reach step 0 and step 1
    int prev = 0; // cost to reach step 0
    int curr = 0; // cost to reach step 1

    for (int i = 0; i < n; i++) {
        int next = Math.min(prev, curr) + cost[i];
        prev = curr;
        curr = next;
    }

    // After the loop, curr is the cost to reach the top (step n),
    // and prev is the cost to reach step n-1.
    return Math.min(prev, curr);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        return 0;
    }
    int n = cost.length;
    if (n <= 1) {
        return 0;
    }
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        // dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2])
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }

    int prevPrev = cost[0]; // dp[i-2]
    int prev = cost[1];     // dp[i-1]
    for (int i = 2; i < n; i++) {
        int curr = Math.min(prevPrev, prev) + cost[i];
        prevPrev = prev;
        prev = curr;
    }
    return Math.min(prevPrev, prev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("cost array cannot be null or empty");
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at the top without paying any cost
        return 0;
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    try {
        if (cost == null) {
            throw new IllegalArgumentException("cost array cannot be null");
        }
        int n = cost.length;
        if (n == 0) {
            return 0;
        }
        if (n == 1) {
            return cost[0];
        }
        int prevPrev = 0; // dp[i-2]
        int prev = 0;     // dp[i-1]
        int curr = 0;
        for (int i = 2; i <= n; i++) {
            curr = Math.min(prev + cost[i - 1], prevPrev + cost[i - 2]);
            prevPrev = prev;
            prev = curr;
        }
        return prev;
    } catch (Exception e) {
        throw new RuntimeException("Error computing minimum cost", e);
    }
}

