public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k < 0) {
        throw new IllegalArgumentException("k must be non‑negative");
    }
    // Edge cases
    if (k == 0) {
        // Only the empty string is required
        return true;
    }
    if (s.length() < k) {
        return false;
    }
    // Number of distinct binary strings of length k
    long totalCodes = 1L << k;
    // If totalCodes is too large to materialise in an array, use a HashSet
    java.util.Set<Long> seen;
    if (totalCodes <= Integer.MAX_VALUE) {
        seen = new java.util.HashSet<>((int)totalCodes);
    } else {
        seen = new java.util.HashSet<>();
    }

    long mask = totalCodes - 1;
    long current = 0;
    // Build the first window
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    seen.add(current);

    // Slide through the string
    for (int i = 1; i <= s.length() - k; i++) {
        // Shift left by one and mask to keep only k bits
        current = ((current << 1) & mask) | (s.charAt(i + k - 1) - '0');
        seen.add(current);
        // Early exit: if we've already seen all possible codes
        if (seen.size() == totalCodes) {
            return true;
        }
    }
    return seen.size() == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    if (k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    // For k >= 63, 1L << k would overflow. In that case it's impossible to contain all codes
    if (k >= 63) return false;
    long max = 1L << k; // number of possible codes
    java.util.Set<Long> seen = new java.util.HashSet<>( (int)max );
    long mask = max - 1L;
    long val = 0L;
    for (int i = 0; i < n; i++) {
        // shift left and add current bit
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(val);
            if (seen.size() == max) return true;
        }
    }
    return seen.size() == max;
}

public boolean hasAllCodes(String s, int k) {
    // Handle null input
    if (s == null) return false;
    // If k is negative or zero, edge cases
    if (k <= 0) return true; // every binary string of length 0 (empty string) is present
    // If k is too large to handle (exceeds int shift limits)
    if (k >= 31) return false;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;          // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int curr = 0;
    // Build initial k-bit value
    for (int i = 0; i < k; i++) {
        curr = (curr << 1) | (s.charAt(i) - '0');
    }
    seen[curr] = true;
    int count = 1;
    // Slide window through the string
    for (int i = k; i < n; i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[curr]) {
            seen[curr] = true;
            count++;
            // Early exit if all codes found
            if (count == total) return true;
        }
    }
    return count == total;
}

