    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask; // drop bits beyond k
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) {
                return true; // early exit if all codes have been seen
            }
        }
    }
    return count == total;
