    // Split sentence into words using one or more whitespace characters
    String[] words = sentence.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        if (words[i].startsWith(searchWord)) {
            return i + 1; // 1‑based index
        }
    }
    return -1;
}

