    }

    int balance = 0;   // number of unmatched '('
    int insertions = 0; // number of insertions required so far

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                // Match with an existing '('
                balance--;
            } else {
                // Need to insert a '(' before this ')'
                insertions++;
            }
        } else {
            // In case of unexpected characters, ignore them
            // (or alternatively throw an exception)
            continue;
        }
    }

    // Any remaining unmatched '(' need ')' insertions
    insertions += balance;
    return insertions;
}

