    int maxSoFar = Integer.MIN_VALUE;
    int minSoFar = Integer.MAX_VALUE;

    for (int num : nums) {
        // Max subarray ending here
        maxEndingHere = Math.max(num, maxEndingHere + num);
        if (maxEndingHere > maxSoFar) {
            maxSoFar = maxEndingHere;
        }

        // Min subarray ending here
        minEndingHere = Math.min(num, minEndingHere + num);
        if (minEndingHere < minSoFar) {
            minSoFar = minEndingHere;
        }
    }

    // The maximum absolute sum is the greater of the maximum subarray sum
    // and the absolute value of the minimum subarray sum.
    return Math.max(maxSoFar, -minSoFar);
}

