            // but we guard against it just in case.
            throw new IllegalStateException("Unable to find a suitable Fibonacci number.");
        }
        remaining -= (int) fib[idx];
        count++;
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    // combine small ascending and large descending
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        // k-th factor is in the large list, which is in descending order of factors
        int indexInLarge = k - small.size() - 1;
        return large.get(large.size() - 1 - indexInLarge);
    }
}

public int kthFactor(int n, int k) {
