    int sqrt = (int) Math.sqrt(n);
    for (int d = 1; d <= sqrt; d++) {
        if (n % d == 0) {
            lower.add(d);
            int other = n / d;
            if (other != d) {
                upper.add(other);
            }
        }
    }
    int total = lower.size() + upper.size();
    if (k > total) {
        return -1;
    }
    if (k <= lower.size()) {
        return lower.get(k - 1);
    } else {
        int idx = k - lower.size() - 1; // 0-based index in the reversed upper list
        return upper.get(upper.size() - 1 - idx);
    }
}

public int kthFactor(int n, int k) {
