        int sqrt = (int) Math.sqrt(n);
        for (int i = 1; i <= sqrt; i++) {
            if (n % i == 0) {
                factors.add(i);
                int counterpart = n / i;
                if (i != counterpart) {
                    factors.add(counterpart);
                }
            }
        }
        java.util.Collections.sort(factors);
        return k <= factors.size() ? factors.get(k - 1) : -1;
    } catch (Exception e) {
        // Any unexpected runtime issues result in -1.
        return -1;
    }
}

