public int kthFactor(int n, int k) {
    // Validate input: both n and k must be positive
    if (n <= 0 || k <= 0) {
        return -1;
    }
    // Lists to store factors below and above sqrt(n)
    java.util.ArrayList<Integer> smaller = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> larger = new java.util.ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            smaller.add(i);
            int other = n / i;
            if (other != i) {
                larger.add(other);
            }
        }
    }
    // Combine to ascending order: smaller (already ascending) + reversed larger
    // Because larger was added in ascending order of i, but those correspond to descending values of n/i.
    java.util.Collections.reverse(larger);
    int totalFactors = smaller.size() + larger.size();
    if (k > totalFactors) {
        return -1;
    }
    // Find kth factor
    if (k <= smaller.size()) {
        return smaller.get(k - 1);
    } else {
        return larger.get(k - smaller.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return "";
    }
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0 && Math.abs(sb.charAt(len - 1) - c) == 32) {
            sb.deleteCharAt(len - 1); // remove the previous character
            continue; // skip appending the current character
        }
        sb.append(c);
    }
    return sb.toString();
}

public String makeGood(String s) {
