public String makeGood(String s) {
    try {
        if (s == null) return null;
        int n = s.length();
        char[] stack = new char[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (size > 0) {
                char top = stack[size - 1];
                if (Math.abs(top - c) == 32) {
                    size--; // remove the bad pair
                    continue;
                }
            }
            stack[size++] = c; // push current character
        }
        return new String(stack, 0, size);
    } catch (Exception e) {
        // Handle unexpected runtime issues gracefully
        return "";
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) return 0;
    int[] best = new int[1];
    Set<String> used = new HashSet<>();
    dfs(s, 0, used, best);
    return best[0];
}

private void dfs(String s, int idx, Set<String> used, int[] best) {
    if (idx == s.length()) {
        best[0] = Math.max(best[0], used.size());
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String part = s.substring(idx, end);
        if (!used.contains(part)) {
            used.add(part);
            dfs(s, end, used, best);
            used.remove(part);
        }
    }
}

