}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    // Use memoization to store best result from each position with respect to current set of seen substrings.
    // Since the set of seen substrings can vary, memoizing on position alone is not enough.
    // However, due to the small input size (n <= 16), we can perform DFS without memoization.
    return dfs(0, new java.util.HashSet<String>(), s, n);
}

private int dfs(int pos, java.util.Set<String> seen, String s, int n) {
    if (pos == n) {
        return 0;
    }
    int best = Integer.MIN_VALUE;
    for (int end = pos + 1; end <= n; end++) {
        String sub = s.substring(pos, end);
        if (seen.contains(sub)) {
            continue;
        }
        seen.add(sub);
        int result = dfs(end, seen, s, n);
        seen.remove(sub);
        if (result != Integer.MIN_VALUE) {
            best = Math.max(best, result + 1);
        }
    }
    return best;
}

