private int dfs(String s, int index, java.util.Set<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int best = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (used.contains(sub)) {
            continue;
        }
        used.add(sub);
        int cur = 1 + dfs(s, end, used);
        if (cur > best) {
            best = cur;
        }
        used.remove(sub);
    }
    return best;
}

public int minOperations(String[] logs) {
    int depth = 0;
    if (logs == null) {
        return 0;
    }
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        String cmd = log.trim();
        if (cmd.equals("./")) {
            // Stay in the current folder; do nothing.
            continue;
        } else if (cmd.equals("../")) {
            // Move up one folder, but cannot go above the root.
            if (depth > 0) {
                depth--;
            }
        } else if (cmd.endsWith("/")) {
            // Enter a new folder.
            depth++;
        }
        // Any other string is treated as malformed and ignored.
    }
    // The current depth represents the number of steps needed to return to root.
    return depth;
}

