public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    try {
        if (low > high) {
            return result; // empty list
        }
        // Clamp low to non-negative
        low = Math.max(low, 0);
        // If 0 is within range, add it
        if (low <= 0 && 0 <= high) {
            result.add(0);
        }
        // BFS from 1 through 9
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i <= high) {
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int lastDigit = curr % 10;

            // Generate next digits: lastDigit - 1 and lastDigit + 1
            for (int diff = -1; diff <= 1; diff += 2) {
                int nextDigit = lastDigit + diff;
                if (nextDigit < 0 || nextDigit > 9) {
                    continue;
                }
                long newNumberLong = (long) curr * 10 + nextDigit;
                if (newNumberLong > high) {
                    continue;
                }
                int newNumber = (int) newNumberLong;
                if (newNumber >= low && newNumber <= high) {
                    result.add(newNumber);
                }
                queue.offer(newNumber);
            }
        }
        Collections.sort(result);
    } catch (Exception e) {
        // In case of unexpected errors, return an empty list
        result = new ArrayList<>();
    }
    return result;
}

