    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0] == null ? 0 : mat[0].length;
    if (n == 0) {
        return 0;
    }

    // Validate that the matrix is rectangular
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0;
        }
    }

    int max = 0;
    int[][] hor = new int[m][n];
    int[][] ver = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];

    try {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    hor[i][j] = (j > 0 ? hor[i][j - 1] : 0) + 1;
                    ver[i][j] = (i > 0 ? ver[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;

                    int localMax = hor[i][j];
                    if (ver[i][j] > localMax) localMax = ver[i][j];
                    if (diag[i][j] > localMax) localMax = diag[i][j];
                    if (anti[i][j] > localMax) localMax = anti[i][j];
                    if (localMax > max) {
                        max = localMax;
                    }
                } else {
                    hor[i][j] = ver[i][j] = diag[i][j] = anti[i][j] = 0;
                }
            }
        }
    } catch (Exception e) {
        // If any runtime exception occurs, return the current best result
        return max;
    }

    return max;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    for (int i = 0; i < m; i++) {
        if (mat[i].length != n) {
            throw new IllegalArgumentException("All rows of the matrix must have the same length.");
        }
    }

    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = 1 + (j > 0 ? horizontal[i][j - 1] : 0);
                vertical[i][j]   = 1 + (i > 0 ? vertical[i - 1][j] : 0);
                diagonal[i][j]   = 1 + (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0);
                antiDiagonal[i][j] = 1 + (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0);

                int currentMax = Math.max(Math.max(horizontal[i][j], vertical[i][j]),
                                          Math.max(diagonal[i][j], antiDiagonal[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j]   = 0;
                diagonal[i][j]   = 0;
                antiDiagonal[i][j] = 0;
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle negative numbers
    boolean negative = n < 0;
    int absN = Math.abs(n);
    // Convert number to string
    String s = Integer.toString(absN);
    int len = s.length();

    // Special case: 0
    if (len == 1) {
        return s;
    }

    StringBuilder result = new StringBuilder();

    // Determine size of the first group
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }

    result.append(s, 0, firstGroup);

    // Append remaining groups with '.' separator
    for (int i = firstGroup; i < len; i += 3) {
        result.append('.');
        result.append(s, i, i + 3);
    }

    // Prepend negative sign if necessary
    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

