    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.insert(0, numStr.charAt(i));
        count++;
        if (count == 3 && i > 0) {
            sb.insert(0, '.');
            count = 0;
        }
    }

    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

