    // Handle zero explicitly (no separators needed)
    if (n == 0) {
        return "0";
    }

    // Use long to avoid overflow when negating Integer.MIN_VALUE
    long value = n;
    boolean negative = false;
    if (value < 0) {
        negative = true;
        value = -value; // value is now positive
    }

    String num = Long.toString(value);
    StringBuilder sb = new StringBuilder();

    // Append the leading segment (may be fewer than 3 digits)
    int len = num.length();
    int firstSegment = len % 3;
    if (firstSegment == 0) firstSegment = 3;
    sb.append(num.substring(0, firstSegment));

    // Append remaining segments, separated by '.'
    int pos = firstSegment;
    while (pos < len) {
        sb.append('.');
        sb.append(num.substring(pos, pos + 3));
        pos += 3;
    }

    // Prepend minus sign if the original number was negative
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute possible transitions
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int root = (int) Math.sqrt(sum);
                if (root * root == sum) {
                    can[i][j] = true;
                }
            }
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < memo.length; i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            if (mask == fullMask) return 1;
            int cached = memo[mask][last];
            if (cached != -1) return cached;
            int count = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && can[last][next]) {
                    count += dfs.applyAsInt(mask | (1 << next), next);
                }
            }
            memo[mask][last] = count;
            return count;
        }
    };
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += dfs.applyAsInt(1 << i, i);
    }
    return total;
}

