public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Sort to handle duplicate values efficiently
    int[] values = A.clone();
    java.util.Arrays.sort(values);

    // Precompute adjacency matrix: sum is perfect square
    int maxVal = values[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int s = 0; s * s <= maxSum; ++s) {
        isSquare[s * s] = true;
    }
    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            adj[i][j] = isSquare[values[i] + values[j]];
        }
    }

    int allMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int mask = 0; mask < (1 << n); ++mask) {
        java.util.Arrays.fill(memo[mask], -1);
    }

    java.util.function.BiFunction<Integer, Integer, Long> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Long apply(Integer mask, Integer last) {
            if (mask == allMask) return 1L;
            int memoVal = memo[mask][last];
            if (memoVal != -1) return memoVal;

            long count = 0;
            for (int next = 0; next < n; ++next) {
                if ((mask & (1 << next)) != 0) continue;
                if (!adj[last][next]) continue;
                // Skip duplicate values leading to identical permutations
                if (next > 0 && values[next] == values[next - 1]
                        && ((mask & (1 << (next - 1))) == 0)) continue;
                count += apply(mask | (1 << next), next);
            }
            memo[mask][last] = (int) Math.min(count, Integer.MAX_VALUE);
            return count;
        }
    };

    long total = 0;
    for (int start = 0; start < n; ++start) {
        // Skip duplicate starting values
        if (start > 0 && values[start] == values[start - 1]) continue;
        total += dfs.apply(1 << start, start);
    }

    return (int) Math.min(total, Integer.MAX_VALUE);
}

