        public long applyAsLong(long mask, long lastIdx) {
            int m = (int) mask;
            int last = (int) lastIdx;
            if (m == fullMask) return 1L;
            if (memo[m][last + 1] != -1) return memo[m][last + 1];
            long ans = 0;
