        int nextUgly = Math.min(next2, Math.min(next3, next5));
        dp[i] = nextUgly;

        if (nextUgly == next2) {
            i2++;
            next2 = dp[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = dp[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = dp[i5] * 5;
        }
    }
    return dp[n - 1];
}

