    for (int digit = 1; digit <= 9; digit++) {
        if (digit > n) break;
        dfs(digit, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> res) {
    res.add(current);
    // If multiplying by 10 would exceed n, no further children are possible
    if (current > n / 10) {
        return;
    }
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            break;
        }
        dfs(next, n, res);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    long next = (long) current * 10;
    while (next <= n) {
        dfs((int) next, n, result);
        next++;
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    long current = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) current);

        if (current * 10 <= n) {
            // Go deeper into the next level
            current *= 10;
        } else {
            // Move to the next sibling or climb up the tree
            while (current % 10 == 9 || current == n) {
                current /= 10;
                if (current == 0) {
                    return result;
                }
            }
            current++;
        }
    }

    return result;
}

public static int calculateUniqueSum(int[] nums) {
    try {
        if (nums == null) {
            return 0;
        }
        java.util.Map<Integer, Integer> frequency = new java.util.HashMap<>();
        for (int num : nums) {
            frequency.put(num, frequency.getOrDefault(num, 0) + 1);
        }
        int sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return sum;
    } catch (Exception e) {
        // In case of unexpected runtime errors, return 0 as a safe default
        return 0;
    }
}

