public static int minPerfectSquareSum(int n) {
    // Handle invalid input
    if (n < 0) {
        return -1;
    }
    // Base case
    if (n == 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    // Initialize with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;

    // Dynamic programming to compute minimal counts
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int sq = j * j;
            int candidate = dp[i - sq] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Handle non‑positive inputs: 0 requires 0 squares; negatives are invalid
    if (n <= 0) {
        return 0;
    }

    // dp[i] will hold the minimal number of perfect squares that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0; // base case: zero sum requires zero numbers

    for (int i = 1; i <= n; i++) {
        int minSquares = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int remaining = i - j * j;
            int candidate = dp[remaining] + 1;
            if (candidate < minSquares) {
                minSquares = candidate;
            }
        }
        dp[i] = minSquares;
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n+1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int sq = j * j;
            if (dp[i - sq] + 1 < dp[i]) {
                dp[i] = dp[i - sq] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    // Check 1
    if (isPerfectSquare(n)) return 1;
    // Remove factors of 4
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    // Check two squares
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        if (isPerfectSquare(remainder)) {
            return 2;
        }
    }
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    // 1: perfect square
    int r = (int)Math.sqrt(n);
    if (r * r == n) return 1;
    // remove factor 4
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) return 4;
    // try 2 squares
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        int sr = (int)Math.sqrt(remainder);
        if (sr * sr == remainder) return 2;
    }
    return 3;
}

private static boolean isPerfectSquare(int x) {
    int r = (int) Math.sqrt(x);
    return r * r == x;
}

public static int minPerfectSquareSum(int n) {
    try {
        if (n < 0) return -1;    // invalid input
        if (n == 0) return 0;    // zero requires no squares

        // Check if n itself is a perfect square
        int s = (int) Math.sqrt(n);
        if (s * s == n) return 1;

        // Check if sum of two perfect squares
        for (int i = 1; i * i <= n; i++) {
            int remaining = n - i * i;
            int t = (int) Math.sqrt(remaining);
            if (t * t == remaining) return 2;
        }

        // Apply Legendre's three-square theorem to decide between 3 and 4
        int temp = n;
        while (temp % 4 == 0) temp /= 4;
        if (temp % 8 == 7) return 4;
        return 3;
    } catch (Exception e) {
        // In case of unexpected runtime issues, signal failure
        return -1;
    }
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(c);
        } else {
            word.append(c);
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}

public static String reverseWords(String s) {
    try {
        if (s == null) {
            return null;
        }
        StringBuilder result = new StringBuilder();
        int i = 0;
        int n = s.length();
        while (i < n) {
            if (s.charAt(i) == ' ') {
                result.append(' ');
                i++;
            } else {
                int j = i;
                while (j < n && s.charAt(j) != ' ') {
                    j++;
                }
                for (int k = j - 1; k >= i; k--) {
                    result.append(s.charAt(k));
                }
                i = j;
            }
        }
        return result.toString();
    } catch (Exception e) {
        // In case of unexpected errors, return the original string
        return s;
    }
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Trim only leading/trailing spaces that are not part of the words
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        return "";
    }
    String[] words = trimmed.split("\\s+");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

